          h: 'Дроби: порядок действий и ответ',
          html: String.raw`<p>В заданиях ОГЭ №6 и ЕГЭ №7 ответ всегда записывается <b>целым числом или конечной десятичной дробью</b>. Если у вас получилось $\dfrac{7}{3}$ — где-то ошибка, пересчитайте.</p>
<div class="rule">$$\frac{a}{b}\pm\frac{c}{d}=\frac{ad\pm bc}{bd},\qquad \frac{a}{b}\cdot\frac{c}{d}=\frac{ac}{bd},\qquad \frac{a}{b}:\frac{c}{d}=\frac{a}{b}\cdot\frac{d}{c}.$$<p>Порядок действий: скобки → степени и корни → умножение и деление слева направо → сложение и вычитание.</p></div>
<div class="tip">Если в примере смешаны десятичные и обыкновенные дроби, переводите всё в обыкновенные: $2{,}4=\dfrac{12}{5}$, $1\dfrac{1}{3}=\dfrac{4}{3}$. Сокращать станет проще, а столбик почти не понадобится.</div>
<div class="example"><p><b>Пример.</b> $\left(\dfrac{7}{12}-\dfrac{1}{3}\right)\cdot 3{,}2$.</p><p>$\dfrac{7}{12}-\dfrac{4}{12}=\dfrac{3}{12}=\dfrac14$, затем $\dfrac14\cdot 3{,}2=0{,}8$. Ответ: $0{,}8$.</p></div>
<div class="quick" data-a="1">Вычислите $1{,}2\cdot\dfrac{5}{6}$.</div>`
