          q: 'В магазине стоят два платёжных терминала. Каждый из них может быть неисправен с вероятностью 0,07 независимо от другого. Найдите вероятность того, что хотя бы один терминал исправен.',
          answer: '0,9951',
          hint: 'Противоположное событие — оба терминала неисправны.',
          solution: String.raw`Оба неисправны: $0{,}07\cdot0{,}07=0{,}0049$.<br>Хотя бы один исправен: $1-0{,}0049=0{,}9951$.<br>Ответ: $0{,}9951$.`
