          solution: String.raw`Путь 1: неисправна и забракована: $0{,}05\cdot0{,}98=0{,}049$.<br>Путь 2: исправна и забракована: $0{,}95\cdot0{,}02=0{,}019$.<br>$P=0{,}049+0{,}019=0{,}068$.<br>Ответ: $0{,}068$.`
