          hint: 'Сначала найдите координаты суммы векторов.',
          solution: String.raw`$\vec a+\vec b=(2+4;\,-3+1)=(6;\,-2)$.<br>$\vec a\cdot(\vec a+\vec b)=2\cdot6+(-3)\cdot(-2)=12+6=18$.<br>Ответ: $18$.`
