          solution: String.raw`$\dfrac{\log_3 64}{\log_3 4}=\log_4 64=3$, так как $4^3=64$.<br>Иначе: $\log_3 64=\log_3 4^3=3\log_3 4$, и дробь равна $3$.<br>Ответ: $3$.`
