          q: String.raw`Найдите значение выражения $26\cos\left(\dfrac{3\pi}{2}+\alpha\right)$, если $\cos\alpha=\dfrac{12}{13}$ и $\alpha\in\left(\dfrac{3\pi}{2};\,2\pi\right)$.`,
          answer: '-10',
