          solution: String.raw`$\cos\left(\dfrac{3\pi}{2}+\alpha\right)=\sin\alpha$.<br>$\sin^2\alpha=1-\dfrac{144}{169}=\dfrac{25}{169}$. В IV четверти $\sin\alpha\lt0$, поэтому $\sin\alpha=-\dfrac5{13}$.<br>$26\cdot\left(-\dfrac5{13}\right)=-10$.<br>Ответ: $-10$.`
