          hint: String.raw`Разность между $a_8$ и $a_3$ — это $5d$.`,
          solution: String.raw`$a_8-a_3=5d=-15$, поэтому $d=-3$.<br>$a_{20}=a_3+17d=10-51=-41$.<br>Ответ: $-41$.`
