          id: 'math-inequalities-9', type: 'input', exam: 'ege', difficulty: 3,
          q: String.raw`Решите неравенство $\dfrac{x^2-9}{x^2-4x+3}\ge0$. Сколько целых решений оно имеет на отрезке $[-5;\,5]$?`,
          answer: '6',
