          solution: String.raw`$x^2-4=a$ даёт $x^2=4+a$ — два корня при любом $a\gt0$.<br>$x^2-4=-a$ даёт $x^2=4-a$: два корня при $a\lt4$, один корень $x=0$ при $a=4$, ни одного при $a\gt4$.<br>Всего три корня, когда $a=4$: $x=0$ и $x=\pm2\sqrt2$.<br>Ответ: $4$.`
