          solution: String.raw`Между точками $-3$ и $2$ сумма расстояний равна $5\lt7$, значит, весь отрезок $[-3;\,2]$ подходит.<br>Справа от $2$: $(x-2)+(x+3)=2x+1\lt7\Rightarrow x\lt3$. Слева от $-3$: $(2-x)+(-x-3)=-2x-1\lt7\Rightarrow x\gt-4$.<br>Решение: $(-4;\,3)$; целые числа: $-3;\,-2;\,-1;\,0;\,1;\,2$ — шесть.<br>Ответ: $6$.`
