          solution: String.raw`$|x-3|$ — расстояние от $x$ до $3$, $|x+5|$ — расстояние от $x$ до $-5$. Равноудалённая точка — середина отрезка: $x=\dfrac{3+(-5)}{2}=-1$.<br>Алгебраически: $(x-3)^2=(x+5)^2$, $-6x+9=10x+25$, $-16x=16$, $x=-1$.<br>Ответ: $-1$.`
