          html: String.raw`<p>В заданиях «Найдите все числа, для которых…» ищут закономерность и доказывают, что других нет. Рабочие приёмы:</p>
<ul><li>перейти к <b>арифметической прогрессии</b> для «чисел с заданным остатком»;</li><li>использовать чётность и остатки, чтобы показать, что решение <b>невозможно</b>;</li><li>дать <b>пример</b>, если нужно показать, что ответ достигается.</li></ul>
<div class="example"><p><b>Пример.</b> Сколько существует трёхзначных чисел, кратных 7? Наименьшее — 105, наибольшее — 994. Количество: $\dfrac{994-105}{7}+1=128$. Или так: $\left\lfloor\dfrac{999}{7}\right\rfloor-\left\lfloor\dfrac{99}{7}\right\rfloor=142-14=128$.</p></div>
<div class="trap">Наименьшее число с остатками 1 при делении на 4, 6 и 9 — это НОК$(4,6,9)+1=37$, а не НОК$(4,6,9)=36$ и не произведение $4\cdot6\cdot9+1$.</div>`
